SELECT id, workspace_id, task_id, occurred_at, created_at
FROM task_completion_event
WHERE workspace_id = #{workspaceId}
  AND task_id = #{taskId}
  AND occurred_at <= #{timeoutAt}
ORDER BY occurred_at, id
LIMIT 1

